-- ============================================================================
-- PNITE — 0019: Cadastro inicial do catálogo (nada é publicado automaticamente)
-- ----------------------------------------------------------------------------
-- * Indicadores e visuais do Caminho da Escola: versão 1 em RASCUNHO.
-- * 31 indicadores observados na PNITE (catalogo_pnite_observado.json, 07/11/2026):
--   versão 1 EM REVISÃO, situação metodológica conforme o status técnico
--   observado ('ok' não é aprovação editorial). A exibição atual da frente
--   Transporte Escolar continua como está até decisão do proprietário.
-- * Reconciliação registrada: quantidade da base (44.172) x painel (44.926).
-- ============================================================================

CREATE OR REPLACE FUNCTION pg_temp.cadastrar(p_codigo text, p_slug text, p_tipo text, p_frente text, p_modulo text,
    p_categoria text, p_ordem int, p_estado text, d jsonb) RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_id bigint;
BEGIN
    INSERT INTO catalogo.indicadores (codigo, slug, tipo, frente, modulo, categoria, ordem, criado_por)
    VALUES (p_codigo, p_slug, p_tipo, p_frente, p_modulo, p_categoria, p_ordem, 'migracao 0019') RETURNING id INTO v_id;
    INSERT INTO catalogo.indicador_versoes (indicador_id, versao, titulo, descricao, objetivo, unidade, casas_decimais, visual,
        niveis, dimensoes, formula_texto, calculo, fonte, periodo_referencia, regra_nulos, sentido, situacao_metodologica,
        estado_editorial, responsavel, nota, criado_por)
    VALUES (v_id, 1, d->>'titulo', d->>'descricao', d->>'objetivo', d->>'unidade', COALESCE((d->>'casas')::smallint, 0),
        COALESCE(d->>'visual', 'cartao'),
        CASE WHEN d ? 'niveis' THEN ARRAY(SELECT jsonb_array_elements_text(d->'niveis')) ELSE ARRAY['nacional'] END,
        CASE WHEN d ? 'dimensoes' THEN ARRAY(SELECT jsonb_array_elements_text(d->'dimensoes')) ELSE '{}'::text[] END,
        d->>'formula', NULLIF(d->'calculo', 'null'::jsonb), d->>'fonte', d->>'periodo', d->>'nulos',
        COALESCE(d->>'sentido', 'neutro'), COALESCE(d->>'situacao', 'em_construcao'), p_estado, d->>'responsavel', d->>'nota',
        'migracao 0019');
    PERFORM catalogo.auditar('migracao 0019', 'cadastro_inicial', 'indicador', v_id::text, NULL,
        jsonb_build_object('codigo', p_codigo, 'estado', p_estado), NULL);
END $$;

